{"implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = payload['required_symbols']
    node_by_id = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n.get('parent')
        if p is not None:
            children[p].append(n['id'])
    root_nodes = [n for n in nodes if n['parent'] is None]
    if len(root_nodes) != 1:
        raise ValueError('Invalid tree: must have single root')
    root_id = root_nodes[0]['id']
    candidates = []
    for n in nodes:
        if n['id'] == root_id:
            continue
        if n['symbol'] in required_symbols:
            continue
        if not n['removable']:
            continue
        candidates.append(n)
    candidates.sort(key=lambda n: (-n['depth'], n['id']))
    removed = set()
    removal_order = []
    for n in candidates:
        nid = n['id']
        if nid in removed:
            continue
        if not all(c in removed for c in children[nid]):
            continue
        removed.add(nid)
        removal_order.append(nid)
    retained_ids = sorted([n['id'] for n in nodes if n['id'] not in removed])
    return {'retained_ids': retained_ids, 'removal_order': removal_order}"}
